<?php
declare(strict_types=1);
require_once __DIR__ . '/../middleware/role-check.php';
require_once __DIR__ . '/../config/database.php';
require_once __DIR__ . '/../helpers/notify.php';
header('Content-Type: application/json; charset=utf-8');
requireMarketplaceRole();
if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);echo json_encode(['success'=>false,'message'=>'Method not allowed.']);exit;}
$d=json_decode((string)file_get_contents('php://input'),true);if(!is_array($d)){http_response_code(400);echo json_encode(['success'=>false,'message'=>'Invalid JSON request.']);exit;}
$buyer=(int)getAuthenticatedUserId();$role=(string)getAuthenticatedRole();$listingId=filter_var($d['listing_id']??null,FILTER_VALIDATE_INT);$token=strtolower(trim((string)($d['checkout_token']??'')));$method=(string)($d['payment_method']??'');$outcome=(string)($d['demo_outcome']??'success');$delivery=is_array($d['delivery']??null)?$d['delivery']:[];
if(!$listingId||$listingId<1||!preg_match('/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/',$token)||!in_array($method,['cash_on_delivery','demo_payment'],true)||($method==='demo_payment'&&!in_array($outcome,['success','failure'],true))){http_response_code(422);echo json_encode(['success'=>false,'message'=>'Choose a valid listing and checkout payment details.']);exit;}
foreach(['recipient_name'=>100,'phone'=>30,'address_line'=>255,'city'=>100,'region'=>100,'postal_code'=>20] as $key=>$max){$value=trim((string)($delivery[$key]??''));if($value===''||strlen($value)>$max){http_response_code(422);echo json_encode(['success'=>false,'message'=>'Complete the delivery contact and address fields.']);exit;}$delivery[$key]=$value;}
try{$pdo->beginTransaction();
$existing=$pdo->prepare('SELECT id,order_number,payment_status,order_status,payment_method,total_amount FROM orders WHERE user_id=:user AND checkout_token=:token LIMIT 1 FOR UPDATE');$existing->execute([':user'=>$buyer,':token'=>$token]);if($old=$existing->fetch(PDO::FETCH_ASSOC)){$pdo->commit();echo json_encode(['success'=>true,'message'=>'This checkout was already processed.','order'=>$old]);exit;}
$s=$pdo->prepare("SELECT l.id,l.inventory_id,l.seller_id,l.asking_price,l.status,i.equipment_id,i.quantity,i.status inventory_status,i.assigned_at,e.name,e.access_role FROM resale_listings l JOIN inventory i ON i.id=l.inventory_id JOIN equipment e ON e.id=i.equipment_id WHERE l.id=:id FOR UPDATE");$s->execute([':id'=>$listingId]);$item=$s->fetch(PDO::FETCH_ASSOC);
if(!$item||$item['status']!=='active'||$item['inventory_status']!=='assigned'||(int)$item['quantity']!==1|| (int)$item['seller_id']===$buyer)throw new DomainException('This resale listing is no longer available.');
if(!in_array($item['access_role'],['common',$role],true))throw new DomainException('This equipment is restricted to another account type.');
$cents=(int)round((float)$item['asking_price']*100);if($cents<1)throw new DomainException('The listing price is invalid.');$failed=$method==='demo_payment'&&$outcome==='failure';$paid=$method==='demo_payment'&&!$failed;$payStatus=$failed?'failed':($paid?'paid':'pending');$orderStatus=$failed?'failed':($paid?'processing':'pending');$number='AX-'.date('ymdHis').'-'.strtoupper(bin2hex(random_bytes(3)));$amount=number_format($cents/100,2,'.','');
$o=$pdo->prepare('INSERT INTO orders (user_id,order_number,checkout_token,order_status,payment_method,payment_status,total_amount) VALUES (:user,:number,:token,:status,:method,:payment,:amount)');$o->execute([':user'=>$buyer,':number'=>$number,':token'=>$token,':status'=>$orderStatus,':method'=>$method,':payment'=>$payStatus,':amount'=>$amount]);$orderId=(int)$pdo->lastInsertId();
$pdo->prepare('INSERT INTO order_delivery_details (order_id,recipient_name,phone,address_line,city,region,postal_code,delivery_notes) VALUES (:order,:name,:phone,:address,:city,:region,:postal,:notes)')->execute([':order'=>$orderId,':name'=>$delivery['recipient_name'],':phone'=>$delivery['phone'],':address'=>$delivery['address_line'],':city'=>$delivery['city'],':region'=>$delivery['region'],':postal'=>$delivery['postal_code'],':notes'=>trim((string)($delivery['delivery_notes']??''))?:null]);
$line=$pdo->prepare('INSERT INTO order_items (order_id,equipment_id,equipment_name,quantity,unit_price,line_total,resale_listing_id,seller_id,inventory_id) VALUES (:order,:equipment,:name,1,:unit_price,:line_total,:listing,:seller,:inventory)');$line->execute([':order'=>$orderId,':equipment'=>$item['equipment_id'],':name'=>$item['name'],':unit_price'=>$amount,':line_total'=>$amount,':listing'=>$listingId,':seller'=>$item['seller_id'],':inventory'=>$item['inventory_id']]);
$reference=($method==='demo_payment'?'DEMO-':'COD-').strtoupper(bin2hex(random_bytes(8)));$pdo->prepare('INSERT INTO payment_transactions (order_id,transaction_reference,payment_method,amount,payment_status,is_simulated) VALUES (:order,:reference,:method,:amount,:status,:simulated)')->execute([':order'=>$orderId,':reference'=>$reference,':method'=>$method,':amount'=>$amount,':status'=>$payStatus,':simulated'=>$method==='demo_payment'?1:0]);
if($failed){$pdo->commit();$message=sprintf('Payment failed for resale order %s. The listing remains available.',$number);createNotification($pdo,$buyer,'Payment failed',$message,'warning');notifyAdminsOfActivity($pdo,$buyer,'Resale payment failed',$message,'warning');http_response_code(402);echo json_encode(['success'=>false,'message'=>'Demonstration payment failed. The listing remains available.','order'=>['id'=>$orderId,'order_number'=>$number,'payment_status'=>$payStatus]]);exit;}
if($paid){$pdo->prepare("UPDATE resale_listings SET status='sold',reservation_order_id=:order,sold_at=CURRENT_TIMESTAMP WHERE id=:id AND status='active'")->execute([':order'=>$orderId,':id'=>$listingId]);$pdo->prepare("UPDATE inventory SET status='sold',sale_price=:price,sold_at=CURRENT_TIMESTAMP WHERE id=:id AND user_id=:seller AND status='assigned'")->execute([':price'=>$amount,':id'=>$item['inventory_id'],':seller'=>$item['seller_id']]);$pdo->prepare('INSERT INTO inventory (user_id,equipment_id,quantity,status,purchase_price,assigned_at,notes) VALUES (:user,:equipment,1,"assigned",:price,CURRENT_TIMESTAMP,:notes)')->execute([':user'=>$buyer,':equipment'=>$item['equipment_id'],':price'=>$amount,':notes'=>'Resale order '.$number]);}
else{$pdo->prepare("UPDATE resale_listings SET status='reserved',reservation_order_id=:order WHERE id=:id AND status='active'")->execute([':order'=>$orderId,':id'=>$listingId]);}
$pdo->commit();$message=$paid?sprintf('Resale order %s completed; ownership has been transferred.',$number):sprintf('Resale order %s was placed and the listing is reserved.',$number);createNotification($pdo,$buyer,$paid?'Resale purchase complete':'Resale order placed',$message,'success');createNotification($pdo,(int)$item['seller_id'],$paid?'Your resale item was sold':'Your resale listing was reserved',$paid?sprintf('Your listing sold in order %s.',$number):sprintf('Your listing is reserved for order %s until payment is confirmed.',$number),'success');notifyAdminsOfActivity($pdo,$buyer,'Resale purchase activity',$message,'info');echo json_encode(['success'=>true,'message'=>$paid?'Simulated payment confirmed; ownership transferred. No real money was charged.':'COD order placed. The listing is reserved until fulfillment/payment confirmation.','order'=>['id'=>$orderId,'order_number'=>$number,'order_status'=>$orderStatus,'payment_status'=>$payStatus,'payment_method'=>$method,'payment_reference'=>$reference,'total_amount'=>(float)$amount,'simulated'=>$method==='demo_payment']]);
}catch(DomainException $e){if($pdo->inTransaction())$pdo->rollBack();http_response_code(409);echo json_encode(['success'=>false,'message'=>$e->getMessage()]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('AETHERYX resale checkout: '.$e->getMessage());http_response_code(500);echo json_encode(['success'=>false,'message'=>'Resale checkout could not be completed.']);}
